import math
import numpy as np
from numba import njit

@njit
def stats(a):
    out = np.empty(3)
    out[0] = a.mean()
    out[1] = math.sqrt(((a - a.mean()) ** 2).sum() / a.size)
    out[2] = np.argmax(a)
    return out

print(stats(np.array([1.0, 2.0, 3.0, 10.0])))  # [4.         3.53553391 3.        ]

@njit
def bad(xs):
    return [x for x in xs] + ["oops"]   # mixes float and str

try:
    bad(np.ones(2))
except Exception as e:
    print(type(e).__name__)             # TypingError

import numpy as np
from numba import njit, typeof, float64

print(typeof(np.zeros((2, 3))))     # array(float64, 2d, C)
print(typeof(np.zeros(4)[::2]))     # array(float64, 1d, A)
print(typeof(3), typeof(2.5))       # int64 float64

@njit(float64(float64[::1], float64))   # compiled eagerly, at definition
def scale_sum(a, k):
    return (a * k).sum()

print(scale_sum(np.ones(3), 2.0))   # 6.0
print(scale_sum.signatures)         # [(Array(float64, 1, 'C', False, aligned=True), float64)]
try:
    scale_sum(np.ones(3, dtype=np.int64), 2.0)
except TypeError as e:
    print("TypeError:", str(e)[:40])  # No matching definition for argument ...

@njit
def overflow(n):
    return n * n
print(overflow(2**40))              # 0  (int64 wrap-around, Python gives 1208925819614629174706176)

import numpy as np
from numba import vectorize, guvectorize, float64

@vectorize([float64(float64, float64)])
def rel_diff(x, y):
    return 2 * (x - y) / (x + y)

a = np.array([1.0, 2.0, 4.0])
print(rel_diff(a, 2.0))                 # [-0.66666667  0.          0.66666667]  (broadcast)
print(rel_diff(a[:, None], a).shape)    # (3, 3)

@guvectorize([(float64[:], float64, float64[:])], "(n),()->(n)")
def clip_row(row, limit, out):
    for i in range(row.shape[0]):
        out[i] = min(row[i], limit)

m = np.array([[1.0, 5.0], [7.0, 2.0]])
print(clip_row(m, 3.0))                 # [[1. 3.]
                                        #  [3. 2.]]

import numpy as np
from numba import njit, types
from numba.typed import Dict, List

@njit
def count_values(a):
    counts = Dict.empty(key_type=types.int64, value_type=types.int64)
    for x in a:
        counts[x] = counts.get(x, 0) + 1
    return counts

c = count_values(np.array([3, 1, 3, 3, 2]))
print(dict(c))                      # {3: 3, 1: 1, 2: 1}

@njit
def evens_up_to(n):
    out = []                        # inferred as a typed list of int64
    for i in range(n):
        if i % 2 == 0:
            out.append(i)
    return out

print(list(evens_up_to(7)))         # [0, 2, 4, 6]
lst = List([1.5, 2.5])
print(type(lst).__name__)           # List

import numpy as np
from numba import njit, prange, get_num_threads

@njit(parallel=True)
def pairwise_min_dist(p):
    n = p.shape[0]
    out = np.empty(n)
    for i in prange(n):                 # rows processed in parallel
        best = np.inf
        for j in range(n):
            if i != j:
                best = min(best, ((p[i] - p[j]) ** 2).sum())
        out[i] = np.sqrt(best)          # each i writes only out[i]: safe
    return out

@njit(parallel=True)
def total(a):
    s = 0.0
    for i in prange(a.size):
        s += a[i]                       # recognised reduction
    return s

pts = np.random.default_rng(0).random((2000, 3))
print(pairwise_min_dist(pts).shape, get_num_threads())  # (2000,) 8  (your core count)
print(total(np.ones(1_000_000)))        # 1000000.0

import numpy as np
from numba import njit

@njit(fastmath=True)
def fast_sum(a):
    s = 0.0
    for x in a:
        s += x            # may be reordered and vectorized
    return s

@njit(error_model="numpy")
def safe_ratio(a, b):
    return a / b

@njit(boundscheck=True)
def get(a, i):
    return a[i]

a = np.random.default_rng(0).random(10_000_000)
print(np.isclose(fast_sum(a), a.sum()))   # True (last bits may differ)
print(safe_ratio(1.0, 0.0))               # inf  (Python error model would raise)
try:
    get(np.zeros(5), 10)
except IndexError as e:
    print("IndexError:", e)               # IndexError: index is out of bounds

import time
import numpy as np
from numba import njit, objmode
from numba.core.errors import TypingError

@njit
def broken(flag):
    x = 1
    if flag:
        x = "one"           # int in one branch, str in the other
    return x

try:
    broken(True)
except TypingError as e:
    print("Cannot unify" in str(e))  # True: the reason is near the end of the message

@njit
def timed_sum(a):
    with objmode(t0="float64"):    # interpreter block inside compiled code
        t0 = time.perf_counter()
    s = a.sum()
    return s, t0 > 0

print(timed_sum(np.ones(10)))      # (10.0, True)

import numpy as np
from numba import njit, types
from numba.extending import overload

def clamp(x, lo, hi):                     # plain Python version
    return min(max(x, lo), hi)

@overload(clamp)
def ol_clamp(x, lo, hi):                  # receives Numba types
    if isinstance(x, types.Array):
        def impl(x, lo, hi):
            out = np.empty_like(x)
            for i in range(x.size):
                out.flat[i] = min(max(x.flat[i], lo), hi)
            return out
        return impl
    if isinstance(x, (types.Integer, types.Float)):
        return lambda x, lo, hi: min(max(x, lo), hi)
    return None                           # unsupported types

@njit
def use(a):
    return clamp(a, 0.0, 1.0), clamp(2.5, 0.0, 1.0)

print(use(np.array([-1.0, 0.5, 3.0])))    # (array([0. , 0.5, 1. ]), 1.0)
